      "inputSchema": {
        "type": "object",
        "properties": {
          "pattern": {
            "type": "integer"
          }
        },
        "required": [
          "pattern"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "pattern_set_length",
      "description": "Set pattern row count",
      "inputSchema": {
        "type": "object",
        "properties": {
          "pattern": {
            "type": "integer"
          },
          "rows": {
            "type": "integer"
          }
        },
        "required": [
          "pattern",
          "rows"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "cell_clear",
      "description": "Clear one pattern cell",
      "inputSchema": {
        "type": "object",
        "properties": {
          "pattern": {
            "type": "integer"
          },
          "row": {
            "type": "integer"
          },
          "channel": {
            "type": "integer"
          }
        },
        "required": [
          "pattern",
          "row",
          "channel"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "sample_save",
      "description": "Save a sample to disk",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          },
          "instrument": {
            "type": "integer"
          },
          "sample": {
            "type": "integer"
          },
          "format": {
            "type": "string",
            "enum": [
              "wav",
              "iff",
              "raw"
            ]
          }
        },
        "required": [
          "path",
          "instrument"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "sample_set",
      "description": "Set sample metadata",
      "inputSchema": {
        "type": "object",
        "properties": {
          "instrument": {
            "type": "integer"
          },
          "sample": {
            "type": "integer"
          },
          "name": {
            "type": "string"
          },
          "volume": {
            "type": "integer"
          },
          "panning": {
            "type": "integer"
          },
          "finetune": {
            "type": "integer"
          },
          "relative_note": {
            "type": "integer"
          },
          "loop_start": {
            "type": "integer"
          },
          "loop_length": {
            "type": "integer"
          },
          "flags": {
            "type": "integer"
          }
        },
        "required": [
          "instrument"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "sample_create_from_pcm",
      "description": "Create sample from base64 PCM",
      "inputSchema": {
        "type": "object",
        "properties": {
          "instrument": {
            "type": "integer"
          },
          "sample": {
            "type": "integer"
          },
          "pcm": {
            "type": "string"
          },
          "encoding": {
            "type": "string",
            "enum": [
              "int16",
              "float32"
            ]
          },
          "name": {
            "type": "string"
          }
        },
        "required": [
          "instrument",
          "pcm"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "instrument_set",
      "description": "Set instrument metadata",
      "inputSchema": {
        "type": "object",
        "properties": {
          "instrument": {
            "type": "integer"
          },
          "name": {
            "type": "string"
          }
        },
        "required": [
          "instrument"
        ],
        "additionalProperties": false
      }
    }
  ]
